/**
 * Generates every token level, the component CSS and the token graph data.
 *
 * Sources: src/tokens/{primitives,semantic}.ts, each component's schema.ts and
 * optional tokens.ts. Generated files carry a header and are never edited.
 */
import { existsSync, mkdirSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { primitives, palettes } from "../src/tokens/primitives";
import { semantic, light } from "../src/tokens/semantic";
import {
  generateComponent, generateTokenHierarchy, toCSSVariables, validateFoundations,
  type Spec, type ComponentTokens, type Token,
} from "../src/tokens/generate";
import { emitComponentCSS } from "../src/tokens/css";

const root = join(fileURLToPath(import.meta.url), "../..");
const COMPONENTS = join(root, "src/components");
const OUT = join(root, "src/styles/tokens");
const GENERATED = join(root, "src/styles/generated");
const DIST = join(root, "dist");

const loadSpecs = async (): Promise<Spec[]> => {
  const specs: Spec[] = [];
  for (const entry of readdirSync(COMPONENTS, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const schema = join(COMPONENTS, entry.name, "schema.ts");
    if (!existsSync(schema)) continue;
    const { meta } = await import(schema);
    if (!meta) throw new Error(`${entry.name}/schema.ts has no \`meta\` export`);
    const tokensFile = join(COMPONENTS, entry.name, "tokens.ts");
    const tokens = existsSync(tokensFile) ? (await import(tokensFile)).tokens : undefined;
    specs.push({ meta, tokens, source: `src/components/${entry.name}` });
  }
  const seen = new Set<string>();
  for (const s of specs) {
    if (seen.has(s.meta.name)) throw new Error(`component name "${s.meta.name}" is used twice`);
    seen.add(s.meta.name);
  }
  return specs.sort((a, b) => a.meta.name.localeCompare(b.meta.name));
};

const header = (name: string) =>
  `/* ${name} — generated by scripts/emit-tokens.ts from src/tokens. Do not edit. */\n\n`;

const decls = (entries: Readonly<Record<string, string>>, indent = "  ") =>
  Object.entries(entries).map(([k, v]) => `${indent}--${k}: ${v};`);

const rootBlock = (lines: string[]) => [":root {", ...lines, "}", ""].join("\n");

const emitLevel = (title: string, all: ComponentTokens[], pick: (c: ComponentTokens) => Token[]) =>
  header(title) +
  rootBlock(all.flatMap((c) => {
    const tokens = pick(c);
    if (!tokens.length) return [];
    return [`  /* ${c.name} */`, ...tokens.map((t) =>
      `  ${t.name}: ${t.value};${t.overridden ? " /* override */" : ""}`)];
  }));

const refsOf = (value: string) => [...value.matchAll(/var\(\s*--([\w-]+)/g)].map((m) => m[1]!);

const tokenData = (level: string, name: string, value: string, component?: string) =>
  ({ name, value, level, component, refs: refsOf(value),
     family: name.slice(2).split("-")[0]! });

const emitL2 = () => {
  const lightLines = decls(light);
  const paletteBlocks = palettes.flatMap((p) =>
    [`:root[data-palette="${p}"] {`, `  --color-palette: var(--color-${p});`, "}", ""]);
  return header("L2 Semantic") +
    rootBlock(["  color-scheme: dark;", ...decls(semantic)]) +
    paletteBlocks.join("\n") + "\n" +
    `@media (prefers-color-scheme: light) {\n  :root:not([data-theme="dark"]) {\n    color-scheme: light;\n${lightLines.join("\n")}\n  }\n}\n\n` +
    `:root[data-theme="light"] {\n  color-scheme: light;\n${lightLines.join("\n")}\n}\n`;
};

const emitTokensCSS = (all: ComponentTokens[]) =>
  header("All tokens") +
  rootBlock([...decls(primitives), ...decls(semantic), ...all.flatMap((c) =>
    c.all.map((t) => `  ${t.name}: ${t.value};`))]);

const write = (dir: string, name: string, content: string) => {
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, name), content);
  console.log(`wrote ${dir.replace(root + "/", "")}/${name}`);
};

validateFoundations();
const specs = await loadSpecs();
const generated = specs.map(generateComponent);

if (process.argv.includes("--show")) {
  for (const s of specs) {
    const h = generateTokenHierarchy(s.meta);
    console.log(JSON.stringify(h, null, 2));
    console.log(JSON.stringify(toCSSVariables(h), null, 2));
  }
  process.exit(0);
}

mkdirSync(DIST, { recursive: true });
write(OUT, "l1-primitives.css", header("L1 Primitives") + rootBlock(decls(primitives)));
write(OUT, "l2-semantic.css", emitL2());
write(OUT, "l3-component.css", emitLevel("L3 Component", generated, (c) => c.l3));
write(OUT, "l4-variant.css", emitLevel("L4 Variant", generated, (c) => c.l4));
write(OUT, "l5-state.css", emitLevel("L5 State", generated, (c) => c.l5));

const css = emitComponentCSS(generated);
write(GENERATED, "elements.css", header("Element component CSS") +
  `@layer wacss.elements {\n${css.elements}\n}\n`);
write(GENERATED, "components.css", header("Class component CSS") +
  `@layer wacss.components {\n${css.components}\n}\n`);

const graph = {
  L1: Object.entries(primitives).map(([k, v]) => tokenData("L1", `--${k}`, v)),
  L2: Object.entries(semantic).map(([k, v]) => tokenData("L2", `--${k}`, v)),
  L3: generated.flatMap((c) => c.l3.map((t) => tokenData("L3", t.name, t.value, c.name))),
  L4: generated.flatMap((c) => c.l4.map((t) => tokenData("L4", t.name, t.value, c.name))),
  L5: generated.flatMap((c) => c.l5.map((t) => tokenData("L5", t.name, t.value, c.name))),
};
write(DIST, "tokens.json", JSON.stringify(graph, null, 2));
write(DIST, "tokens.css", emitTokensCSS(generated));

const count = (f: (c: ComponentTokens) => Token[]) => generated.reduce((n, c) => n + f(c).length, 0);
console.log(`generated ${specs.length} specs: L1 ${graph.L1.length}, L2 ${graph.L2.length}, ` +
  `L3 ${count((c) => c.l3)}, L4 ${count((c) => c.l4)}, L5 ${count((c) => c.l5)}`);
